entries[191480] = { ["name"] = "Skeletal Steed", ["text"] = "Binds when picked up\nUnique\nDuration: 1 hour\nMount\nRequires Level 40\nUse: Summons and dismisses a skeletal steed. This steed is obedient to the summoner and can be used as a mount within Naxxramas. Any hostile action towards the rider forces the steed to run away in fear. (3 Sec Cooldown)" }
