entries[203745] = { ["name"] = "Spell Notes: Ice Lance", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nRequiresEngraving\n(1)\nEngrave your gloves with the Ice Lance rune:\n\nDeals [source value] to [source value] Frost damage to an enemy target. Causes 400% damage against Frozen targets.\n\nWhen your other frost spells deal damage to a non-player controlled target, they increase the target's damage taken from your next Ice Lance by 20%. This effect stacks up to 5 times and requires the Winter's Chill talent.\n\"Teaches you a new Runecarving ability.\"", ["unresolvedValues"] = true }
entries[203746] = { ["name"] = "Spell Notes: Living Flame", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nRequiresEngraving\n(1)\nEngrave your pants with the Living Flame rune:\n\nSummons a spellfire flame that moves toward the target, leaving a trail of spellfire. This trail deals [source value] Spellfire damage every second to nearby enemies. Lasts 10 sec.\n\"Teaches you a new Runecarving ability.\"", ["unresolvedValues"] = true }
entries[203747] = { ["name"] = "Spell Notes: Fingers of Frost", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nRequiresEngraving\n(1)\nEngrave your chest or robe with the Fingers of Frost rune:\n\nGives your Chill effects a 25% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen. Lasts 15 sec.\n\"Teaches you a new Runecarving ability.\"" }
entries[203748] = { ["name"] = "Spell Notes: Burnout", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your chest with the Burnout rune:\n\nIncreases your spell critical strike chance with all spells by 15%, but your non-periodic spell critical strikes now have an additional mana cost of 1% of your base mana.\n\"Teaches you a new Engraving ability.\"" }
entries[203749] = { ["name"] = "Spell Notes: Enlightenment", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your chest or robe with the Enlightenment rune:\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting.\n\"Teaches you a new Engraving ability.\"" }
