entries[203990] = { ["name"] = "Rune of Mutilation", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your gloves with the Mutilate rune:\n\nInstantly attacks with both weapons for 95% weapon damage plus an additional [source value] with each weapon. Damage is increased by 20% against Poisoned targets. Awards 2 combo points.\n\nMutilate benefits from all talents and effects that trigger from or modify Backstab unless otherwise specified.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[203991] = { ["name"] = "Rune of Quick Draw", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Quick Draw rune:\n\nDraw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by 50% for 6 sec. Awards 1 combo point.\n\nQuick Draw benefits from all talents and effects that trigger from or modify Sinister Strike.\n\"Teaches you a new Engraving ability.\"" }
entries[203992] = { ["name"] = "Rune of Trickery", ["text"] = "Classes: Rogue\n\"Teaches you a new Engraving ability.\"" }
entries[203993] = { ["name"] = "Rune of Slaughter", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Slaughter from the Shadows rune:\n\nReduces the Energy cost of your Backstab and Ambush abilities by 30, and increases the damage they deal to non-player controlled targets by 70%. [ Engrave Gloves - Mutilate : Does not apply to Mutilate / Does not apply to abilities learned from other runes.]\n\"Teaches you a new Engraving ability.\"" }
entries[203994] = { ["name"] = "Rune of Deadly Brew", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Deadly Brew rune:\n\nGrants several improvements to your poisons:\n\nWhen you inflict any other poison on a target, you also inflict Deadly Poison.\n\nIf your weapon does not have a poison applied, it has a chance to trigger Instant Poison as if Instant Poison were applied.\n\nDeadly Poison and Instant Poison now gain increased damage from your Attack Power.\n\nYour Deadly Poison can now be active on targets affected by another Rogue's Deadly Poison.\n\"Teaches you a new Engraving ability.\"" }
entries[204174] = { ["name"] = "Rune of Precision", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your pants with the Between the Eyes rune:\n\nRanged Finishing move that causes damage per combo point, increased by Attack Power, and Stuns the target:\n\n1 point: [source value] to [source value] damage, 1 sec Stun\n2 points: [source value] to [source value] damage, 2 sec Stun\n3 points: [source value] to [source value] damage, 3 sec Stun\n4 points: [source value] to [source value] damage, 4 sec Stun\n5 points: [source value] to [source value] damage, 5 sec Stun\n\nCooldown shared with Kidney Shot.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
