entries[204441] = { ["name"] = "Rune of Blood Frenzy", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your chest with the Blood Frenzy rune:\n\nRend can now be used in Berserker stance, Rend's damage is increased by 100%, and Rend deals additional damage equal to 4% of your Attack Power each time it deals damage.\n\"Teaches you a new Engraving ability.\"" }
