entries[211385] = { ["name"] = "Rune of Serpent Spread", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your pants with the Serpent Spread rune:\n\nTargets hit by your Multi-Shot are also afflicted by your Serpent Sting for 12 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[211386] = { ["name"] = "Spell Notes: Arcane Surge", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your pants with the Arcane Surge rune:\n\nUnleash all of your remaining mana in a surge of energy focused at the target dealing [source value] to [source value] Arcane damage, increased by up to 300% based on your mana remaining. Afterward, your normal mana regeneration is activated and increased by 300% for 8 sec.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211387] = { ["name"] = "Rune of Beckoning Light", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your gloves with the Beacon of Light rune:\n\nThe target becomes a Beacon of Light to all members of your party or raid within a 40 yard radius. Any heals you cast on party or raid members will also heal the Beacon for 75% of the amount healed. Only one target can be the Beacon of Light at a time. Lasts 1 hour.\n\"Teaches you a new Engraving ability.\"" }
entries[211390] = { ["name"] = "Rune of Teasing", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Just a Flesh Wound rune:\n\nYou take 20% reduced Physical damage while Blade Dance is active, reduced by an additional 1% for every 12 of your Defense skill beyond ( 60 * 5). Additionally, your chance to Dodge is multiplied by 50%, you have 6% reduced chance to be critically hit by melee attacks, you deal 20% less damage, the threat generated by all your actions is massively increased, and your Feint ability is replaced with Tease, which Taunts the target to attack you.\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\"Teaches you a new Engraving ability.\"" }
entries[211391] = { ["name"] = "Rune of Healing Rain", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your chest or robe with the Healing Rain rune:\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [source value] every second.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211392] = { ["name"] = "Rune of Everlasting Affliction", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your pants with the Everlasting Affliction rune:\n\nDrain Life, Drain Soul, Shadowbolt, Shadow Cleave, Searing Pain, Incinerate, and Haunt refresh the duration of your Corruption on the target back to its maximum duration.\n\"Teaches you a new Engraving ability.\"" }
entries[211393] = { ["name"] = "Rune of Single-Minded Fury", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your gloves with the Single-Minded Fury rune:\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 4% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target.\n\"Teaches you a new Engraving ability.\"" }
entries[211419] = { ["name"] = "Handful of Shifting Scales", ["text"] = "Binds when picked up\nUnique\n\"These curious scales seem to shimmer slightly, as if they are not fully corporeal. There is clearly wonderous magic at play here... if only you could find someone who knows more about them.\"" }
entries[211420] = { ["name"] = "Shifting Scale Talisman", ["text"] = "Binds when picked up\nTrinket\n+5 Spirit\nRequires Level 25\nEquip: Protects the bearer from the effects of Crushing Darkness." }
entries[211421] = { ["name"] = "The Box", ["text"] = "Binds when picked up\nUnique\nUse: Attempt to use a powerful source of The Light to destroy The Box.\n\"Touching the box with your bare hands immediately fills you with a sense of deep disquiet... but also, a sense of creative inspiration like you've never felt before.\"" }
entries[211422] = { ["name"] = "Shard of the Void", ["text"] = "Binds when picked up\nUnique\n\"All that remains of the box is a tiny sliver of perfectly black crystal. It seems to draw in and consume the light.\"" }
entries[211423] = { ["name"] = "Void-Touched Leather Gloves", ["text"] = "Binds when picked up\nUnique-Equipped: Void-Touched (1)\nHands Leather\n110 Armor\n+6 Agility\n+6 Stamina\n+4 Spirit\nDurability 70 / 70\nRequires Level 25\nRequires Leatherworking (100)\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nUse: Descend into madness, increasing attack speed by 10% as well as increasing the threat you generate for 10 sec. (10 Min Cooldown)" }
entries[211426] = { ["name"] = "Bough of Shadows", ["text"] = "Binds when picked up\nUnique\n\"Tainted by the Emerald Nightmare, this splinter drains the life of its possessor.\"" }
entries[211427] = { ["name"] = "Soul Vessel", ["text"] = "\"Traps demon souls and siphons them for power.\"" }
