entries[211498] = { ["name"] = "Trainee's Sentinel Nightsaber", ["text"] = "Binds when picked up\nMount\nRequires any Alliance race\nRequires Level 25\nUse: Summons a Trainee's Sentinel Nightsaber. Only usable in Ashenvale. (3 Sec Cooldown)" }
entries[211499] = { ["name"] = "Trainee's Outrider Wolf", ["text"] = "Binds when picked up\nMount\nRequires any Horde race\nRequires Level 25\nUse: Summons a Trainee's Outrider Wolf. Only usable in Ashenvale. (3 Sec Cooldown)" }
entries[211500] = { ["name"] = "Resilient Cloth Headband", ["text"] = "Binds when picked up\nUnique\nHead Cloth\n50 Armor\nDurability 50 / 50\nRequires Level 20\nEquip: Reduces all damage taken and chance to be critically hit by 5% in Warsong Gulch." }
entries[211501] = { ["name"] = "Chestguard of Might", ["text"] = "Binds when picked up\nChest Plate\n749 Armor\n+27 Strength\n+18 Stamina\n+10 Fire Resistance\nDurability 165 / 165\nClasses: Warrior\nRequires Level 60\nEquip: Improves your chance to get a critical strike by 1%.\nEquip: Improves your chance to hit by 1%." }
entries[211502] = { ["name"] = "Void-Touched Leather Gauntlets", ["text"] = "Binds when picked up\nUnique-Equipped: Void-Touched (1)\nHands Leather\n70 Armor\n+5 Stamina\n+7 Intellect\n+6 Spirit\nDurability 70 / 70\nRequires Level 25\nRequires Leatherworking (100)\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nUse: Descend into madness, increasing spell damage by 10% as well as increasing the threat you generate for 10 sec. (10 Min Cooldown)" }
entries[211504] = { ["name"] = "Twilight Avenger's Chain", ["text"] = "Binds when picked up\nChest Mail\n218 Armor\n+9 Strength\n+6 Agility\n+8 Stamina\nDurability 120 / 120\nRequires Level 25\nEquip: Increased Defense +4.\n\nBlackfathom Avenger's Mail (0/3)\nTwilight Avenger's Boots\nTwilight Avenger's Chain\nTwilight Avenger's Helm\n(2) Set : +12 Attack Power.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
entries[211505] = { ["name"] = "Twilight Avenger's Helm", ["text"] = "Binds when picked up\nHead Mail\n176 Armor\n+9 Strength\n+11 Agility\n+3 Stamina\nDurability 70 / 70\nRequires Level 25\nEquip: Increased Defense +4.\n\nBlackfathom Avenger's Mail (0/3)\nTwilight Avenger's Boots\nTwilight Avenger's Chain\nTwilight Avenger's Helm\n(2) Set : +12 Attack Power.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
entries[211506] = { ["name"] = "Twilight Avenger's Boots", ["text"] = "Binds when picked up\nFeet Mail\n150 Armor\n+10 Strength\n+5 Stamina\nDurability 60 / 60\nRequires Level 25\n\nBlackfathom Avenger's Mail (0/3)\nTwilight Avenger's Boots\nTwilight Avenger's Chain\nTwilight Avenger's Helm\n(2) Set : +12 Attack Power.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
entries[211507] = { ["name"] = "Twilight Elementalist's Cowl", ["text"] = "Binds when picked up\nHead Leather\n84 Armor\n+9 Stamina\n+10 Intellect\nDurability 60 / 60\nRequires Level 25\nEquip: Increases damage and healing done by magical spells and effects by up to 8.\n\nBlackfathom Elementalist's Hide (0/3)\nTwilight Elementalist's Cowl\nTwilight Elementalist's Footpads\nTwilight Elementalist's Robe\n(2) Set : Increases damage and healing done by magical spells and effects by up to 12.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
entries[211508] = { ["name"] = "Twilight Elementalist's Footpads", ["text"] = "Binds when picked up\nFeet Leather\n71 Armor\n+5 Agility\n+7 Intellect\n+7 Spirit\nDurability 55 / 55\nRequires Level 25\n\nBlackfathom Elementalist's Hide (0/3)\nTwilight Elementalist's Cowl\nTwilight Elementalist's Footpads\nTwilight Elementalist's Robe\n(2) Set : Increases damage and healing done by magical spells and effects by up to 12.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
entries[211509] = { ["name"] = "Twilight Elementalist's Robe", ["text"] = "Binds when picked up\nChest Leather\n103 Armor\n+10 Stamina\n+10 Intellect\nDurability 100 / 100\nRequires Level 25\nEquip: Increases damage and healing done by magical spells and effects by up to 7.\n\nBlackfathom Elementalist's Hide (0/3)\nTwilight Elementalist's Cowl\nTwilight Elementalist's Footpads\nTwilight Elementalist's Robe\n(2) Set : Increases damage and healing done by magical spells and effects by up to 12.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
entries[211510] = { ["name"] = "Twilight Slayer's Cowl", ["text"] = "Binds when picked up\nHead Leather\n84 Armor\n+10 Agility\n+9 Stamina\nDurability 60 / 60\nRequires Level 25\nEquip: +14 Attack Power.\n\nBlackfathom Slayer's Leather (0/3)\nTwilight Slayer's Cowl\nTwilight Slayer's Footpads\nTwilight Slayer's Tunic\n(2) Set : +12 Attack Power.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
entries[211511] = { ["name"] = "Twilight Slayer's Footpads", ["text"] = "Binds when picked up\nFeet Leather\n71 Armor\n+5 Strength\n+7 Agility\n+7 Stamina\nDurability 55 / 55\nRequires Level 25\n\nBlackfathom Slayer's Leather (0/3)\nTwilight Slayer's Cowl\nTwilight Slayer's Footpads\nTwilight Slayer's Tunic\n(2) Set : +12 Attack Power.\n(3) Set : Improves your chance to hit with all spells and attacks by 1%." }
