entries[211514] = { ["name"] = "Spell Notes: Mass Regeneration", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your pants with the Mass Regeneration rune:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\nTemporal Beacon\n\nRecords the subject's space-time position. 70% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211527] = { ["name"] = "Cozy Sleeping Bag", ["text"] = "Binds when picked up\nUnique\nUse: Unfurl a sleeping bag. Resting inside for at least one minute will provide a bonus to experience earned, stacking up to 3 times. (1 Hour Cooldown)\n\"Old, but still good\"" }
entries[211528] = { ["name"] = "Dark Insight", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Consider at a certain secluded grave in Duskwood to receive a prophecy." }
entries[211530] = { ["name"] = "Prophecy of a City Enthralled", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your bracers with the Power Word: Barrier rune:\n\nSummons a holy barrier to protect all party members at the target location for 10 sec, reducing all damage taken by 25% and preventing damage from delaying spellcasting.\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[211531] = { ["name"] = "Prophecy of Seven Visitors", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your chest or robe with the Strength of Soul rune:\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal.\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[211534] = { ["name"] = "Primal Insight", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Consider at a Thistlefur dreamcatcher high in the canopy to receive a prophecy." }
entries[211691] = { ["name"] = "Spell Notes: Arcane Blast", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your gloves with the Arcane Blast rune:\n\nBlasts the target with energy, dealing [source value] to [source value] Arcane damage. Each time you cast Arcane Blast, the damage of all other Arcane spells is increased by 15% and mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 6 sec or until any other Arcane damage spell is cast.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
