entries[212225] = { ["name"] = "Neverending Soul Vessel", ["text"] = "Binds when picked up\nUnique\nUse: Your next Soul Shard consuming spell cost no Soul Shards to cast. (5 Min Cooldown)" }
entries[212230] = { ["name"] = "Schematic: Soul Vessel", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse: Teaches you how to make a Soul Vessel.\nSoul Vessel\n\"Traps demon souls and siphons them for power.\"\nRequires Shadowgem (4), Black Vitriol , Demonic Figurine" }
