entries[213451] = { ["name"] = "Corrupted Fire Totem", ["text"] = "Binds when picked up\nUnique\n\"Tainted by the influence of the Burning Blade, this totem is gnarled, blackened, and scarred, but you can sense the element within. Surely someone else will be as concerned as you are with this discovery.\"" }
entries[213452] = { ["name"] = "Dormant Holy Rune", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\n\"First, you must lay down your life for another. Then, before your spirit departs, have your salvation returned in kind.\"" }
entries[213513] = { ["name"] = "Libram of Deliverance", ["text"] = "Binds when picked up\nUnique\nRelic Libram\nClasses: Paladin\nRequires Level 18\nEngrave your boots with the Sacred Shield rune:\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [source value] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time.\n\"Learn a new ability after using Blessing of Freedom to free others from movement impairing effects 5 times.\"", ["unresolvedValues"] = true }
entries[213526] = { ["name"] = "Hybrid Haunch", ["text"] = "Binds when picked up\nUnique\n\"Tastes like beef *and* chicken.\"" }
entries[213527] = { ["name"] = "Smuggler's Spice Blend", ["text"] = "Binds when picked up\nUnique\n\"The crown jewel of any ship's galley. Could make a boot taste good.\"" }
