entries[215369] = { ["name"] = "Pattern: Invoker's Cord", ["text"] = "Requires Tailoring (150)\nUse: Teaches you how to sew Invoker's Cord.\nInvoker's Cord\nBinds when equipped\nWaist Cloth\n24 Armor\n+5 Intellect\nDurability 25 / 25\nRequires Level 25\nEquip: Increases damage and healing done by magical spells and effects by up to 7.\nRequires Bolt of Silk Cloth (3), Shadowgem , Fine Thread , Gray Dye" }
entries[215370] = { ["name"] = "Pattern: Invoker's Mantle", ["text"] = "Requires Tailoring (150)\nUse: Teaches you how to sew Invoker's Mantle.\nInvoker's Mantle\nBinds when equipped\nShoulder Cloth\n32 Armor\n+5 Intellect\nDurability 45 / 45\nRequires Level 25\nEquip: Increases damage and healing done by magical spells and effects by up to 7.\nRequires Bolt of Silk Cloth (4), Gray Dye (4), Fine Thread , Blue Dye (4)" }
entries[215371] = { ["name"] = "Jani's Charm", ["text"] = "Binds when equipped\nUnique\nTrinket\nClasses: Rogue" }
entries[215373] = { ["name"] = "Silver Hand Training Hammer", ["text"] = "Two-Hand Mace\n17 - 54 Damage Speed 3.40\n(10.44 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Recovered from Theramore Isle where its owner was slain in battle against bloodthirsty orcish hordes.\"" }
entries[215374] = { ["name"] = "Ancestral Sword", ["text"] = "Two-Hand Sword\n17 - 46 Damage Speed 3.10\n(10.16 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Passed down by a noble Lordaeron family. Once thought to be lost in the swamps around Kyross along with the last warrior to wield it.\"" }
entries[215375] = { ["name"] = "Tactician's Staff", ["text"] = "Two-Hand Staff\n16 - 49 Damage Speed 3.50\n(9.29 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Its owner's keen grasp of battlefield tactics was matched only by her fearsome command of frost and flame.\"" }
entries[215376] = { ["name"] = "Crusader's Mace", ["text"] = "Main Hand Mace\n21 - 36 Damage Speed 2.90\n(9.83 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Flecked with dried bits of insect carapace.\"" }
entries[215377] = { ["name"] = "Irradiated Robe", ["text"] = "Binds when picked up\nChest Cloth\n65 Armor\n-5 Strength\n-10 Stamina\n+7 Intellect\n+8 Spirit\n+7 Nature Resistance\nDurability 80 / 80\nRequires Level 40\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 23.\n\nIrradiated Garments (0/3)\nIrradiated Robe\nIrradiated Trousers\nIrradiated Boots\n(2) Set : -5 Stamina.\n(2) Set : Improves your chance to get a critical strike with all spells and attacks by 1%.\n(3) Set : Increases damage and healing done by magical spells and effects by up to 11." }
entries[215378] = { ["name"] = "Irradiated Boots", ["text"] = "Binds when picked up\nFeet Cloth\n45 Armor\n-5 Agility\n-10 Stamina\n+12 Intellect\n+11 Spirit\nDurability 40 / 40\nRequires Level 40\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 11.\n\nIrradiated Garments (0/3)\nIrradiated Robe\nIrradiated Trousers\nIrradiated Boots\n(2) Set : -5 Stamina.\n(2) Set : Improves your chance to get a critical strike with all spells and attacks by 1%.\n(3) Set : Increases damage and healing done by magical spells and effects by up to 11." }
entries[215379] = { ["name"] = "Irradiated Trousers", ["text"] = "Binds when picked up\nLegs Cloth\n57 Armor\n-5 Agility\n-10 Stamina\n+10 Intellect\n+13 Spirit\n+10 Nature Resistance\nDurability 75 / 75\nRequires Level 40\nEquip: Increases damage and healing done by magical spells and effects by up to 16.\nEquip: Restores 4 mana per 5 sec.\n\nIrradiated Garments (0/3)\nIrradiated Robe\nIrradiated Trousers\nIrradiated Boots\n(2) Set : -5 Stamina.\n(2) Set : Improves your chance to get a critical strike with all spells and attacks by 1%.\n(3) Set : Increases damage and healing done by magical spells and effects by up to 11." }
entries[215380] = { ["name"] = "Power-Assisted Lifting Belt", ["text"] = "Binds when picked up\nWaist Mail\n168 Armor\n+14 Strength\n+15 Stamina\nDurability 50 / 50\nRequires Level 40\nEquip: Increased Two-handed Axes +3.\nEquip: Increased Two-handed Swords +3.\nEquip: Increased Two-handed Maces +3." }
entries[215381] = { ["name"] = "Gneuro-Conductive Channeler's Hood", ["text"] = "Binds when picked up\nHead Leather\n118 Armor\n+11 Stamina\n+12 Intellect\n+11 Spirit\nDurability 70 / 70\nRequires Level 40\nRequires Leatherworking (225)\nEquip: Increases damage and healing done by magical spells and effects by up to 21.\nUse: Gain gneuromantic meditation, allowing 100% of your mana regeneration to continue while casting and increasing damage and healing done by spells by up to 50 for 20 sec. (10 Min Cooldown)" }
entries[215382] = { ["name"] = "Rad-Resistant Scale Hood", ["text"] = "Binds when picked up\nHead Mail\n342 Armor\n+10 Stamina\n+10 Intellect\nDurability 85 / 85\nRequires Level 40\nRequires Leatherworking (225)\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: +32 Attack Power.\nUse: Engage the radiation mitigation protocols in this helmet, causing you to immediately remove all active poison effects and gain immunity to all Nature damage for 3 sec. (10 Min Cooldown)" }
entries[215383] = { ["name"] = "Plans: Reflective Truesilver Braincage", ["text"] = "Binds when picked up\nRequires Blacksmithing (225)\nUse: Teaches you how to make a Reflective Truesilver Braincage.\nReflective Truesilver Braincage\nBinds when picked up\nHead Plate\n426 Armor\n+14 Stamina\n+15 Intellect\nDurability 100 / 100\nRequires Level 40\nRequires Blacksmithing (225)\nEquip: Increases damage and healing done by magical spells and effects by up to 21.\nUse: Gain reinforced willpower, preventing Silence, Interrupt effects, and spell pushback for 10 sec. (10 Min Cooldown)\nRequires Mithril Bar (25), Low-Background Truesilver Plates (4), Hyperconductive Arcano-Filament (2), Polished Truesilver Gears" }
entries[215384] = { ["name"] = "Plans: Low-Background Truesilver Plates", ["text"] = "Binds when picked up\nRequires Blacksmithing (200)\nUse: Teaches you how to make Low-Background Truesilver Plates.\nLow-Background Truesilver Plates\nRequires Truesilver Bar , Reflective Scrapmetal (5)" }
