entries[215437] = { ["name"] = "Trogg Transfigurator 3000", ["text"] = "Binds when picked up\nRequires Level 40\nUse: Transfigures the caster into a Trogg. (30 Min Cooldown)\n\"Typically used for reconnaissance.\"" }
