entries[215468] = { ["name"] = "Orders from the Grand Crusader", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The letter is crumpled and there are flecks of dried blood on it.\"" }
entries[215683] = { ["name"] = "Geomancy: The Stone-Cold Truth", ["text"] = "Binds when picked up\nUnique\n\"Theories on the origin and usage of elemental magic. A fine addition to any library's collection.\"" }
